"""CPU log plotting; previews are generated by the leased GPU worker."""
import json
from pathlib import Path


def records(path):
    path = Path(path)
    return [json.loads(line) for line in path.read_text().splitlines()] if path.exists() else []


def plot_run(output):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    train = records(output / 'history.jsonl')
    validation = records(output / 'validation_history.jsonl')
    fig, axes = plt.subplots(1, 4, figsize=(16, 3.5))
    if train:
        axes[0].plot([r['images_seen'] / 10000 for r in train], [r['train_loss'] for r in train], label='Train')
    if validation:
        x = [r['images_seen'] / 10000 for r in validation]
        for ax, key in zip(axes[:3], ['selection_loss', 'psnr_mean_per_image', 'lpips']):
            ax.plot(x, [r[key] for r in validation], label='Validation')
        if 'genes_used' in validation[-1]:
            axes[3].plot(x, [r['genes_used'] for r in validation])
    for ax, title in zip(axes, ['L1 + 0.1 LPIPS', 'Validation PSNR', 'Validation LPIPS', 'Genes used on validation']):
        ax.set(title=title, xlabel='Training dataset passes')
        ax.grid(alpha=0.2)
    if train:
        axes[0].legend()
    fig.suptitle(output.name)
    fig.tight_layout()
    partial = output / 'loss_curves.partial.png'
    fig.savefig(partial, dpi=130)
    plt.close(fig)
    partial.replace(output / 'loss_curves.png')


def comparison(root, variants):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    from PIL import Image, ImageDraw
    summaries, panels = {}, []
    fig, axes = plt.subplots(1, 3, figsize=(13, 3.5))
    for variant in variants:
        output = root / 'runs' / variant
        points = records(output / 'validation_history.jsonl')
        for ax, key in zip(axes, ['selection_loss', 'psnr_mean_per_image', 'lpips']):
            if points:
                ax.plot([p['images_seen'] / 10000 for p in points], [p[key] for p in points], label=variant)
        metrics = output / 'test_metrics.json'
        if metrics.exists():
            summaries[variant] = json.loads(metrics.read_text())
        preview = output / 'previews/test_best.png'
        if preview.exists():
            panels.append((variant, Image.open(preview).convert('RGB')))
    for ax, title in zip(axes, ['Validation objective', 'Validation PSNR', 'Validation LPIPS']):
        ax.set(title=title, xlabel='Training dataset passes')
        ax.grid(alpha=0.2)
        if ax.lines:
            ax.legend(fontsize=7)
    fig.tight_layout()
    fig.savefig(root / 'reports/comparison_curves.png', dpi=130)
    plt.close(fig)
    (root / 'reports/comparison_metrics.json').write_text(json.dumps(summaries, indent=2) + '\n')
    if panels:
        sheet = Image.new('RGB', (sum(im.width for _, im in panels), max(im.height for _, im in panels) + 24), 'white')
        draw = ImageDraw.Draw(sheet)
        x = 0
        for name, panel in panels:
            draw.text((x + 3, 3), name, fill='black')
            sheet.paste(panel, (x, 24))
            x += panel.width
        sheet.save(root / 'reports/test_reconstruction_comparison.png')
